/**
 * routes.ts — the 24 campaign boards (transcribed exactly from
 * specs/campaign-boards.md) with one solving route set per board, produced
 * by solver.ts and stored as data so course-walk helpers can replay them
 * move-by-move (each route is an ordered cell list, [col, row] pairs,
 * starting at one of the channel's emitters). nodeCounts is the node
 * multiset by notation character, for the boards-as-written check.
 *
 * GENERATED by gen-routes.mts — regenerate rather than editing routes.
 */

import type { Channel } from "./notation";

export interface CampaignBoardData {
  /** Board number, 1..CAMPAIGN_LENGTH, in play order. */
  board: number;
  cols: number;
  rows: number;
  /** Board notation, rows joined by \n, exactly as specs/campaign-boards.md writes it. */
  notation: string;
  /** Node multiset by notation character (boards-as-written check). */
  nodeCounts: Record<string, number>;
  /** One solving route per channel present: ordered [col, row] cells, emitter to emitter. */
  routes: Partial<Record<Channel, ReadonlyArray<readonly [number, number]>>>;
}

